diff --git a/src/test/fuzz/http_request.cpp b/src/test/fuzz/http_request.cpp
index 59422eac9e..735bc6946b 100644
--- a/src/test/fuzz/http_request.cpp
+++ b/src/test/fuzz/http_request.cpp
@@ -32,7 +32,7 @@ void CheckBodyMatchesFraming(const HTTPRequest& req)
     const std::string body{req.ReadBody()};
     const auto transfer_encoding{req.GetHeader("Transfer-Encoding")};
     const auto content_length{req.GetHeader("Content-Length")};
-    if (transfer_encoding && ToLower(*transfer_encoding) == "chunked") {
+    if (transfer_encoding) {
         assert(body.size() <= MAX_BODY_SIZE);
     } else if (content_length) {
         const auto parsed_length{ToIntegral<uint64_t>(*content_length)};
diff --git a/src/httpserver.cpp b/src/httpserver.cpp
index dc2b8e8310..58d370ab90 100644
--- a/src/httpserver.cpp
+++ b/src/httpserver.cpp
@@ -428,11 +428,30 @@ bool HTTPRequest::LoadHeaders(LineReader& reader)
     return m_headers.Read(reader);
 }

+//! The only transfer coding we support is "chunked". It must be the final
+//! coding and cannot be applied twice, so it must be the only one listed.
+//! https://httpwg.org/specs/rfc9112.html#field.transfer-encoding
+static void RequireChunkedOnly(const std::vector<std::string_view>& transfer_encoding_values)
+{
+    size_t num_codings{0};
+    for (const auto value : transfer_encoding_values) {
+        for (const auto coding : Split<std::string_view>(value, ",")) {
+            const auto trimmed{util::TrimStringView(coding)};
+            if (trimmed.empty()) continue;
+            if (ToLower(trimmed) != "chunked") throw std::runtime_error("Unsupported Transfer-Encoding");
+            ++num_codings;
+        }
+    }
+    if (num_codings != 1) throw std::runtime_error("Unsupported Transfer-Encoding");
+}
+
 bool HTTPRequest::LoadBody(LineReader& reader)
 {
     // https://httpwg.org/specs/rfc9112.html#message.body
-    auto transfer_encoding_header = m_headers.FindFirst("Transfer-Encoding");
-    if (transfer_encoding_header && ToLower(transfer_encoding_header.value()) == "chunked") {
+    // Transfer-Encoding takes precedence over Content-Length.
+    const auto transfer_encoding_values{m_headers.FindAll("Transfer-Encoding")};
+    if (!transfer_encoding_values.empty()) {
+        RequireChunkedOnly(transfer_encoding_values);
         // Transfer-Encoding: https://datatracker.ietf.org/doc/html/rfc7230.html#section-3.3.1
         // Chunked Transfer Coding: https://datatracker.ietf.org/doc/html/rfc7230.html#section-4.1
         // see evhttp_handle_chunked_read() in libevent http.c
diff --git a/test/functional/interface_http.py b/test/functional/interface_http.py
index 61bb30bbe7..04ab4bc863 100755
--- a/test/functional/interface_http.py
+++ b/test/functional/interface_http.py
@@ -158,6 +158,7 @@ class HTTPBasicsTest (BitcoinTestFramework):
         self.check_disallowed_http_methods()
         self.check_path_traversal()
         self.check_request_smuggling_cl_te()
+        self.check_transfer_encoding_not_chunked()
         self.check_duplicate_content_length()
         self.check_null_byte_in_uri()
         self.check_invalid_http_version()
@@ -570,6 +571,33 @@ class HTTPBasicsTest (BitcoinTestFramework):
         assert f'"result":{count}' in response


+    def check_transfer_encoding_not_chunked(self):
+        self.log.info("Check that a Transfer-Encoding other than a single chunked is rejected")
+        # https://www.rfc-editor.org/rfc/rfc9112#section-6.3
+        # Only a single "chunked" coding is supported. Anything else gets a
+        # 400 rather than a body framed by Content-Length.
+        body = '{"method":"getblockcount"}'
+        for te_headers in (
+            ["Transfer-Encoding: gzip"],
+            ["Transfer-Encoding: chunked, gzip"],
+            ["Transfer-Encoding: chunked", "Transfer-Encoding: gzip"],
+            ["Transfer-Encoding: identity", "Transfer-Encoding: chunked"],
+        ):
+            conn = BitcoinHTTPConnection(self.node)
+            raw = (
+                f"POST / HTTP/1.1\r\n"
+                f"Host: {conn.url.hostname}\r\n"
+                f"Authorization: Basic {str_to_b64str(conn.authpair)}\r\n"
+                + "".join(f"{h}\r\n" for h in te_headers) +
+                f"Content-Length: {len(body)}\r\n"
+                f"\r\n"
+                f"{body}"
+            ).encode("ascii")
+            conn.send_raw(raw)
+            response = conn.recv_raw().decode()
+            assert response.startswith("HTTP/1.1 400"), (te_headers, response)
+
+
     def check_duplicate_content_length(self):
         self.log.info("Check that duplicate Content-Length headers are handled")
         # https://www.rfc-editor.org/rfc/rfc7230#section-3.3.3
diff --git a/src/test/httpserver_tests.cpp b/src/test/httpserver_tests.cpp
index 2ac63949fb..e1ea05a8bd 100644
--- a/src/test/httpserver_tests.cpp
+++ b/src/test/httpserver_tests.cpp
@@ -477,6 +477,42 @@ BOOST_AUTO_TEST_CASE(http_request_tests)
         BOOST_CHECK(req.LoadHeaders(reader));
         BOOST_CHECK_EXCEPTION(req.LoadBody(reader), std::runtime_error, HasReason{"Improperly terminated chunk"});
     }
+    {
+        // Transfer coding names are case-insensitive
+        HTTPRequest req;
+        std::string_view ok_chunked = "POST / HTTP/1.1\n"
+                                      "Transfer-Encoding: Chunked\n"
+                                      "\n"
+                                      "1a\n"
+                                      R"({"method":"getblockcount"})""\n"
+                                      "0\n"
+                                      "\n";
+        LineReader reader(ok_chunked, MAX_HEADERS_SIZE);
+        BOOST_CHECK(req.LoadControlData(reader));
+        BOOST_CHECK(req.LoadHeaders(reader));
+        BOOST_CHECK(req.LoadBody(reader));
+        BOOST_CHECK_EQUAL(req.ReadBody(), R"({"method":"getblockcount"})");
+    }
+    // Reject any Transfer-Encoding other than a single "chunked", whatever
+    // Content-Length says and whichever header line carries it
+    for (const std::string_view te : {
+             "Transfer-Encoding: gzip\n",
+             "Transfer-Encoding: identity\n",
+             "Transfer-Encoding: chunked, gzip\n",
+             "Transfer-Encoding: gzip, chunked\n",
+             "Transfer-Encoding: chunked, chunked\n",
+             "Transfer-Encoding: \n",
+             "Transfer-Encoding: chunked\nTransfer-Encoding: gzip\n",
+             "Transfer-Encoding: identity\nTransfer-Encoding: chunked\n",
+             "Transfer-Encoding: chunked\nTransfer-Encoding: chunked\n",
+         }) {
+        HTTPRequest req;
+        const std::string request{strprintf("POST / HTTP/1.1\n%sContent-Length: 26\n\n" R"({"method":"getblockcount"})", te)};
+        LineReader reader(request, MAX_HEADERS_SIZE);
+        BOOST_CHECK(req.LoadControlData(reader));
+        BOOST_CHECK(req.LoadHeaders(reader));
+        BOOST_CHECK_EXCEPTION(req.LoadBody(reader), std::runtime_error, HasReason{"Unsupported Transfer-Encoding"});
+    }
 }

 BOOST_AUTO_TEST_CASE(http_request_state_tests)

